/* ---------------- moved from database.js (E17 phase 4), in its original order ---------------- */
/* Stored or imported state, laid over the defaults with every collection back
   to the type the app expects. A list that came back as null (a hand-edited
   or half-written file) used to throw in the first render and leave the app
   on its loading screen for good (bug sweep 1.3). Only the top level is
   touched: a record inside a list is never rewritten here. */
export function normaliseState(parsed) {
  const plain = v => !!v && typeof v === 'object' && !Array.isArray(v);
  const src = plain(parsed) ? parsed : {};
  const st = Object.assign(structuredClone(DEFAULT_STATE), src);
  Object.keys(DEFAULT_STATE).forEach(k => {
    const d = DEFAULT_STATE[k];
    if (Array.isArray(d)) st[k] = Array.isArray(st[k]) ? st[k].filter(x => x != null) : [];
    else if (plain(d)) { if (!plain(st[k])) st[k] = structuredClone(d); }
    else if (d === null && st[k] != null && !plain(st[k])) st[k] = null;   // active, fitDraft
  });
  // settings is merged a level deeper, so a key added to DEFAULT_STATE later still gets its default
  st.settings = Object.assign(structuredClone(DEFAULT_STATE.settings), plain(src.settings) ? src.settings : {});
  ['customMovements', 'foods'].forEach(k => { if (k in st && !Array.isArray(st[k])) delete st[k]; });   // optional lists, read with || []
  ['workouts', 'checkins', 'goals', 'meets', 'misses'].forEach(k => { st[k] = st[k].filter(plain); });       // lists of records hold only records
  return st;
}
export let freshInstall = false;   // no stored state at boot: What's new has nothing to tell
export async function load() {
  const raw = await storeGet(KEY, true);
  if (!raw) {
    /* A fresh install has nothing to catch up on. Marked here, on the state
       itself, rather than at the end of boot: the first launch reloads when
       the service worker takes over, and a debounced save can be lost to it. */
    freshInstall = true;
    const st = structuredClone(DEFAULT_STATE);
    st.settings.lastSeenVersion = APP_VERSION;
    return st;
  }
  /* Stored data that won't read is never swapped for an empty log (bug sweep
     1.4): the migration below would save that empty log straight over it. It
     throws instead, and boot's rescue screen offers a copy of what's there. */
  let parsed;
  try { parsed = JSON.parse(raw); } catch (e) { throw new Error(`The stored log isn't readable (${e.message})`); }
  {
    const st = fixupState(normaliseState(parsed));   // source and alias repairs, shared with import
    /* 0.25.0: food logging left the app. An empty food log and its targets
       are dropped; one with entries is kept, unshown, until it's exported or
       removed from Clear data — so an update never loses someone's log. */
    if (!(st.foods || []).length) dropFood(st);
    return st;
  }
}
/* ---------------- clearing data ----------------
   Targeted deletions with a count against each, so nothing is removed on a
   vague promise. Every option says exactly how many records it touches and
   asks again before doing it. Erase-all stays separate, below this. */
function clearTargets() {
  const wos = S.workouts || [];
  const customIds = new Set((S.customMovements || []).map(m => m.id));
  const usesCustom = e => e.leaf && customIds.has(e.leaf.movement);
  return [
    { id: 'imported', label: 'Imported sessions',
      note: 'Everything brought in from another app — Liftoff, Strong, Hevy, FitNotes or a CSV.',
      n: wos.filter(w => w.source === 'imported').length,
      run: () => { S.workouts = wos.filter(w => w.source !== 'imported'); } },
    { id: 'backfill', label: 'Backfilled sessions',
      note: "Past plan sessions marked done at their prescribed loads — estimates, not what came off the bar.",
      n: wos.filter(w => w.source === 'backfill').length,
      run: () => { S.workouts = S.workouts.filter(w => w.source !== 'backfill'); } },
    { id: 'planned', label: 'Planned sessions',
      note: 'Future sessions not yet done. Completed training is kept.',
      n: wos.filter(w => w.status === 'planned').length,
      run: () => { S.workouts = S.workouts.filter(w => w.status !== 'planned'); } },
    { id: 'unrecognised', label: 'Unrecognised exercises',
      note: 'Movements the catalogue could not name, and every set logged against them.',
      n: wos.reduce((a, w) => a + (w.exercises || []).filter(usesCustom).length, 0),
      run: () => {
        S.workouts.forEach(w => { w.exercises = (w.exercises || []).filter(e => !usesCustom(e)); });
        S.workouts = S.workouts.filter(w => (w.exercises || []).length);
        S.customMovements = [];
      } },
    { id: 'zerorep', label: 'Zero-rep sets',
      note: 'Sets that came out of the source PDF with no reps at all. They are excluded from history already.',
      n: wos.reduce((a, w) => a + (w.exercises || []).reduce((b, e) => b + (e.sets || []).filter(s => s.needsReview).length, 0), 0),
      run: () => {
        S.workouts.forEach(w => {
          (w.exercises || []).forEach(e => { e.sets = (e.sets || []).filter(s => !s.needsReview); });
          w.exercises = (w.exercises || []).filter(e => (e.sets || []).length);
        });
        S.workouts = S.workouts.filter(w => (w.exercises || []).length);
      } },
    { id: 'food', label: 'Old food log',
      note: S.settings.foodExportedAt ? 'Food logging has left Ironlog. Saved already — safe to remove.'
        : 'Food logging has left Ironlog. Save it first from Settings → Data.',
      n: (S.foods || []).length,
      run: () => dropFood(S) },
    { id: 'aliases', label: 'Remembered import names',
      note: 'The raw-name mappings kept so a re-import does not ask twice.',
      n: Object.keys(S.exAliases || {}).length,
      run: () => { S.exAliases = {}; } },
  ];
}
