async function eraseEverything(forgetKey) {
  clearTimeout(saveTimer); setSavePending(false);
  stopRest();
  try { await driveDisconnect(); } catch (e) { /* offline: the link is dropped below anyway */ }
  try { await idb('readwrite', st => st.clear()); } catch (e) { /* storage down: the fresh log below still replaces the old one */ }
  try { [KEY, VBT_RAW_KEY, 'ironlog.aiUsage'].forEach(k => localStorage.removeItem(k)); } catch (e) { /* blocked */ }
  if (forgetKey) setAiKey('');
  setState(structuredClone(DEFAULT_STATE));
  S.schemaVersion = 2; S.settings.lastSeenVersion = APP_VERSION;
  bustCatalogue(); bust();
  save(); await flush();
  applySkin(S.settings.skin); closeAllModals(); go('home'); toast('All data erased');
}
